:root{--orange:#ff7628;--ink:#060912;--panel:rgba(3,7,15,.91);--muted:#aeb8ca;--line:#ffffff25}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#030711;color:#f0f3fa;font-family:Arial,Helvetica,sans-serif}
body{background:radial-gradient(ellipse at 80% 10%,#12223b 0,transparent 40%),#030711}
button,input,textarea{font:inherit}button{cursor:pointer;color:#fff;background:#111827;border:1px solid #ff7628;border-radius:8px;padding:11px 15px;transition:.18s}button:hover{background:#ff7628;color:#090b10}
button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid #fff;outline-offset:2px}
button.primary{background:#ff7628;color:#0b0d12;font-weight:800;box-shadow:0 0 22px #ff762833}
button.secondary{border-color:#64748b;background:#0a101c}
header{position:relative;padding:17px clamp(14px,3vw,40px);display:flex;justify-content:space-between;align-items:center;gap:15px;border-bottom:1px solid var(--line);background:#030711cc}
.brand{font-size:12px;letter-spacing:.2em;color:#aab6ca;text-transform:uppercase}.brand b{color:var(--orange);display:block;font: bold clamp(19px,2.5vw,28px Georgia,serif);letter-spacing:.04em;margin-top:5px}
.header-actions{display:flex;gap:8px;flex-wrap:wrap}
.progress{height:4px;background:#172033}.progress>div{height:100%;width:0;background:var(--orange);transition:width .3s}
/* main{max-width:1300px;margin:0 auto;padding:clamp(14px,3vw,38px)} */
.screen{display:none;animation:fade .35s ease}.screen.active{display:block}
.screen-main{height: 100vh;background: url('images/background.png') center center / cover no-repeat; }
section{
    padding: 20px 0;
}
.container{width: 80%; margin: 20px auto;}
@keyframes fade{from{opacity:.25;transform:translateY(8px)}to{opacity:1;transform:none}}
.hero{min-height:calc(100vh - 135px);display:grid;grid-template-columns:1fr 1fr;gap:26px;align-items:center}
.hero-image{min-height:390px;border-radius:16px;background-image:linear-gradient(0deg,#02050dcc,transparent 60%),url("data:image/png;base64,");background-size:cover;background-position:center;box-shadow:0 15px 70px #0009;border:1px solid #fff1}
.eyebrow{font-size:12px;letter-spacing:.2em;text-transform:uppercase;color:#b7c2d5;margin-bottom:14px}
h1,h2,h3{font-family:Georgia,'Times New Roman',serif;margin:0 0 15px}h1{font-size:clamp(36px,5.6vw,56px);line-height:.98;text-transform:uppercase;color:var(--orange);text-shadow:0 0 25px #ff762833}h2{font-size:clamp(28px,4vw,48px);color:var(--orange)}h3{font-size:22px;color:#f2a06e}
p{line-height:1.65;color:#d2d9e5}.story{font-size:clamp(15px,1.5vw,19px);max-width:680px}.question{font:italic clamp(19px,2vw,26px) Georgia,serif;color:white;margin:22px 0}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:clamp(18px,3vw,30px);box-shadow:0 15px 50px #0004}
.topline{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:20px}
.kicker{color:var(--orange);font-size:12px;letter-spacing:.15em;text-transform:uppercase}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:18px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.big-emoji{font-size:clamp(50px,8vw,90px);filter:drop-shadow(0 0 15px #ff762833)}
.controls{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}
label{display:block;color:#c7d0df;font-size:14px;margin:12px 0 6px}
input[type=text],textarea,select{width:100%;background:#080e19;border:1px solid #344055;border-radius:8px;padding:12px;color:#fff}
textarea{min-height:75px;resize:vertical}.small{font-size:13px;color:var(--muted)}.notice{padding:12px 14px;border-left:3px solid var(--orange);background:#ff762810;color:#e7eaf0;border-radius:0 8px 8px 0;margin:14px 0}
.card{background:#090f1b;border:1px solid var(--line);border-radius:12px;padding:16px}.card p{margin-bottom:0}.pill{display:inline-block;border:1px solid #ff762866;color:#ffb184;border-radius:100px;padding:5px 9px;font-size:12px}
.navbottom{display:flex;justify-content:space-between;gap:10px;margin-top:24px;flex-wrap:wrap}
.photo-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-top:14px}.photo-slot{min-height:120px;border:1px dashed #69758a;border-radius:10px;overflow:hidden;display:grid;place-items:center;text-align:center;color:#9ca9bd;background:#080d17;position:relative}.photo-slot img{width:100%;height:100%;min-height:120px;object-fit:cover}.photo-slot span{padding:8px;font-size:12px}
.photo-grid.winners{grid-template-columns:repeat(2,minmax(0,1fr));max-width:550px}
.upload{display:inline-flex;gap:8px;align-items:center;border:1px solid #64748b;border-radius:8px;padding:10px 13px;cursor:pointer;margin-top:10px}.upload input{max-width:190px}
.play-area{display:grid;grid-template-columns:1fr auto;gap:18px;align-items:center}
.timer{font:clamp(34px,6vw,66px) Georgia,serif;color:var(--orange);min-width:150px;text-align:center}
.freeze-prompt{font:clamp(22px,3.2vw,38px) Georgia,serif;text-align:center;padding:28px 14px;border-radius:12px;background:linear-gradient(135deg,#101827,#070a11);border:1px solid #ff762866;margin:15px 0}
.choices{display:flex;flex-wrap:wrap;gap:8px}
.monster-image{height:150px;border-radius:10px;background:radial-gradient(ellipse at center,#26364a 0,#0c1422 65%,#070a11 100%);display:grid;place-items:center;font-size:82px;border:1px solid #ffffff20;margin-bottom:12px;overflow:hidden;position:relative}
.monster-image:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,#050811aa,transparent 22%,transparent 78%,#050811aa),linear-gradient(0deg,#05081199,transparent 35%,transparent 70%,#05081199);pointer-events:none}
footer{padding:18px;text-align:center;color:#66738a;font-size:12px}

.envelope-panel{min-height:420px;display:flex;flex-direction:column;justify-content:center;align-items:center}
.envelope-button{position:relative;width:min(440px,85vw);height:260px;border:0;background:transparent;padding:0;margin:8px auto 14px;perspective:1000px;overflow:visible}
.envelope-back{position:absolute;inset:35px 0 0;background:#9b4b20;border-radius:8px;box-shadow:0 15px 35px #0008}
.letter{position:absolute;z-index:2;left:8%;right:8%;bottom:90px;height:205px;padding:24px 18px;background:#f0dfb8;color:#2a1a12;border-radius:3px;box-shadow:0 0 18px #0008;transform:translateY(80px);transition:transform .8s ease,bottom .8s ease;display:flex;flex-direction:column;align-items:center;justify-content:center}
.letter-stamp{font-size:10px;letter-spacing:.2em;color:#9b3c18;margin-bottom:15px}
.letter-text{font: bold clamp(15px,2vw,20px)/1.45 Georgia,serif;text-align:center}
.envelope-flap{position:absolute;z-index:4;top:35px;left:0;width:0;height:0;border-left: min(220px,42.5vw) solid transparent;border-right:min(220px,42.5vw) solid transparent;border-top:135px solid #c66b2f;transform-origin:top;transition:transform .7s ease;filter:drop-shadow(0 4px 3px #0005)}
.envelope-front{position:absolute;z-index:3;left:0;right:0;bottom:0;height:225px;background:linear-gradient(145deg,#d98240,#a94f24);clip-path:polygon(0 0,50% 58%,100% 0,100% 100%,0 100%);border-radius:0 0 8px 8px}
.seal{position:absolute;z-index:5;left:50%;top:148px;transform:translateX(-50%);width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:#581c1c;color:#ffcf91;border:2px solid #d79a54;box-shadow:0 3px 10px #0007;transition:opacity .3s}
.envelope-button.open .envelope-flap{transform:rotateX(180deg);z-index:1}
.envelope-button.open .letter{transform:translateY(-28px);bottom:38px;z-index:5}
.envelope-button.open .seal{opacity:0}
.envelope-button:hover{background:transparent;filter:brightness(1.08)}
@media(max-width:760px){.envelope-button{height:235px}.letter{height:190px}.envelope-flap{border-top-width:120px}.envelope-front{height:200px}.seal{top:135px}}
@media(max-width:760px){.hero,.grid2,.play-area{grid-template-columns:1fr}.hero{min-height:0}.hero-image{min-height:260px;order:2}.grid3{grid-template-columns:1fr 1fr}.photo-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.photo-grid.winners{grid-template-columns:1fr 1fr}.timer{text-align:left;}.header-actions button{padding:8px 10px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}

/* Закрывающаяся дверь при входе в испытание */
.door-transition{position:fixed;inset:0;z-index:9999;display:flex;perspective:1200px;pointer-events:none;background:#02040a;animation:doorFade 4s ease forwards}
.door-panel{position:absolute;top:0;bottom:0;width:50.5%;overflow:hidden;background:linear-gradient(90deg,#2b160d 0%,#6d3c20 12%,#4b2817 48%,#754527 76%,#2c170d 100%);border:8px solid #211109;box-shadow:inset 0 0 24px #130903, inset 0 0 0 4px #9a6338,0 0 30px #000;}
.door-panel:before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 7%,#1d0d0670 7.3% 7.8%,#d79a5840 8% 8.4%,transparent 8.8% 15%),repeating-linear-gradient(0deg,transparent 0 23%,#1b0d0870 23.5% 24.2%,#c18a5140 24.5% 25%,transparent 25.4% 49%);opacity:.9}
.door-panel.left{left:0;transform-origin:left center;animation:doorLeft 1.15s cubic-bezier(.45,0,.8,.5) forwards}
.door-panel.right{right:0;transform-origin:right center;animation:doorRight 1.15s cubic-bezier(.45,0,.8,.5) forwards}
.door-panel:after{content:"";position:absolute;inset:8% 12%;border:10px ridge #8b5933;border-radius:3px;box-shadow:inset 0 0 0 5px #2a150b,inset 0 0 25px #160a04,0 0 0 3px #2b160b;background:linear-gradient(90deg,#5a311b,#754627 50%,#4a2715);opacity:.85}
.door-handle{position:absolute;top:52%;width:17px;height:17px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#ffe0a0,#b17a2f 45%,#3d210c 80%);border:2px solid #241207;box-shadow:0 0 12px #ffbb5540;z-index:4}
.door-panel.left .door-handle{right:16px}.door-panel.right .door-handle{left:16px}
.door-seam{position:absolute;left:50%;top:0;bottom:0;width:10px;background:#000;z-index:3;transform:translateX(-50%)}
@keyframes doorLeft{0%{transform:rotateY(-70deg)}45%{transform:rotateY(0)}100%{transform:rotateY(0)}}
@keyframes doorRight{0%{transform:rotateY(70deg)}45%{transform:rotateY(0)}100%{transform:rotateY(0)}}
@keyframes doorFade{0%,65%{opacity:1}100%{opacity:0;visibility:hidden}}
.notice{padding:0;border-left:0;background:transparent;margin:14px 0;color:#e7eaf0}
.notice details{border-left:3px solid var(--orange);background:#ff762810;border-radius:0 8px 8px 0;padding:11px 14px}
.notice summary{cursor:pointer;color:#ffb184;font-weight:700;list-style:none}
.notice summary::-webkit-details-marker{display:none}.notice summary:before{content:'＋ ';color:var(--orange)}.notice details[open] summary:before{content:'− '}
.notice .notice-content{padding-top:8px;line-height:1.55}


/* Финальная сцена и доска розыгрыша */
.escape-scene{position:relative;display:grid;gap:24px;align-items:center;overflow:hidden;border:1px solid #ffffff20;border-radius:16px;padding:clamp(18px,3vw,34px);background:radial-gradient(ellipse at 30% 50%,#f6b95b28,transparent 42%),linear-gradient(135deg,#111a2b,#030711);margin-bottom:24px}
.escape-door{height:260px;position:relative;display:grid;place-items:center;perspective:700px;background:#080b13;border:12px solid #382316;box-shadow:inset 0 0 0 5px #8a603b,0 12px 30px #0008;overflow:hidden}
.escape-light{position:absolute;inset:-20% -5%;background:radial-gradient(ellipse at 85% 50%,#fff2a6 0,#f9bd5a88 24%,#ff8b291f 48%,transparent 70%);opacity:0;transition:opacity 1.2s;z-index:1}
.escape-door-leaf{position:absolute;inset:0;z-index:2;transform-origin:left center;background:repeating-linear-gradient(90deg,#2c170d 0 8%,#6c3f23 8.5% 10%,#422416 11% 18%);border:8px ridge #9b6b40;box-shadow:inset 0 0 0 5px #281409;transition:transform 1.8s cubic-bezier(.2,.7,.1,1)}
.escape-door-leaf:before{content:"";position:absolute;inset:10%;border:8px ridge #a57646;box-shadow:inset 0 0 0 4px #2b160b}
.escape-door-leaf:after{content:"";position:absolute;right:12%;top:48%;width:18px;height:18px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#ffe6a0,#a56b2b 50%,#241207 80%)}
.escape-scene.opened .escape-door-leaf{transform:rotateY(-105deg)}.escape-scene.opened .escape-light{opacity:1}
.escape-copy p{font-size:clamp(16px,1.6vw,20px);line-height:1.65}.raffle-panel{margin-top:18px}.pinboard{min-height:130px;margin:18px 0;padding:20px;display:grid;grid-template-columns:repeat(auto-fill,minmax(135px,1fr));gap:16px;background:repeating-linear-gradient(0deg,#76522e 0 3px,#815d38 3px 6px);border:9px solid #382316;border-radius:9px;box-shadow:inset 0 0 0 3px #b78b55,0 10px 25px #0007}
.participant-card{position:relative;min-height:145px;padding:14px 8px 12px;text-align:center;background:#f1e4c7;color:#23170e;border-radius:3px;box-shadow:2px 5px 8px #0008;transform:rotate(var(--tilt,-1deg));border:1px solid #d2bd95;overflow:hidden}.participant-card:nth-child(even){--tilt:1.4deg}.pin{position:absolute;top:5px;left:calc(50% - 6px);width:12px;height:12px;border-radius:50%;background:#b02a24;border:2px solid #e5a39a;box-shadow:0 2px 3px #0007;z-index:3}.participant-photo{width:78px;height:78px;margin:9px auto 8px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,#3d2734,#7e4d45);color:#fff;font-size:26px;font-weight:800;overflow:hidden;border:3px solid #c6a66f}.participant-photo img{width:100%;height:100%;object-fit:cover}.participant-name{font-weight:800;overflow-wrap:anywhere}.won-cross{display:none;position:absolute;inset:0;z-index:5;align-items:center;justify-content:center;color:#c91515;font-size:100px;font-family:Arial,sans-serif;font-weight:900;line-height:1;text-shadow:0 0 3px #fff,2px 2px #fff;transform:rotate(-12deg);background:#fff2}.participant-card.won .won-cross{display:flex}.participant-card.won{filter:grayscale(.75);opacity:.78}.participant-card.won:after{content:"УЖЕ ВЫИГРАЛ(А)";position:absolute;bottom:5px;left:0;right:0;font-size:10px;font-weight:900;color:#9e1515;z-index:6}.raffle-controls{display:flex;gap:10px;flex-wrap:wrap}.raffle-result{margin-top:14px;padding:15px;border:1px solid #ff762866;border-radius:10px;background:#ff762811;font-size:18px;font-weight:700;min-height:50px}.participant-upload{width:100%;font-size:10px;margin-top:6px;color:#352519}.participant-upload-label{display:block;font-size:11px;margin-top:5px;color:#5b4027;cursor:pointer;text-decoration:underline}.participant-upload-label input{display:none}

.photo-finale{display:grid;grid-template-columns:minmax(280px,.85fr) minmax(300px,1.15fr);gap:24px;align-items:center;min-height:calc(100vh - 170px)}
.photo-copy{padding:clamp(20px,3vw,36px);border:1px solid #9b6cff66;border-radius:16px;background:linear-gradient(145deg,#151126f2,#080d19f2);box-shadow:0 0 35px #7546bb20}
.photo-title{font:900 clamp(30px,4vw,54px)/1.02 Georgia,serif;color:#f7f0ff;text-transform:uppercase;text-shadow:0 0 22px #a855f766;margin:0 0 20px}
.photo-copy p{font-size:clamp(16px,1.5vw,20px);line-height:1.55;color:#e4e0ef}
.photo-upload{display:inline-block;margin-top:10px;background:#7545a8;border:1px solid #c6a4ff;border-radius:9px;padding:13px 17px;font-weight:800;cursor:pointer;color:white}
.photo-upload input{display:none}.photo-frame{position:relative;min-height:330px;display:flex;align-items:center;justify-content:center;overflow:hidden;border:3px solid #8e64c7;border-radius:15px;background:linear-gradient(135deg,#17172a,#050810);box-shadow:0 0 35px #8b5cf633;}
.photo-frame img{display:block;max-width:100%;max-height:62vh;object-fit:contain;border-radius:7px}
.photo-placeholder{text-align:center;color:#b9a9d5;padding:45px 20px}.photo-placeholder .camera{font-size:68px;display:block;margin-bottom:12px}

.photo-frame .photo-ghost {
  position: absolute;
  top: 3%;
  right: 0;
  width: 22%;
  height: auto;
  object-fit: contain;
  z-index: 5;
  display: none;
  pointer-events: none;
}

.photo-frame.sent .photo-ghost {
  display: block;
  animation: ghostAppear 0.8s ease-out both;
}
@keyframes ghostAppear {
  from {
    opacity: 0;
    transform: translate(16px, -12px) scale(0.4);
  }
  to {
    opacity: 0.96;
    transform: rotate(0deg) scale(1);
  }
}
@media(max-width:760px){.photo-finale{grid-template-columns:1fr;min-height:auto}.photo-frame{min-height:240px}.photo-frame img{max-height:45vh}}
@media(max-width:760px){.escape-scene{grid-template-columns:1fr}.escape-door{height:190px}.pinboard{grid-template-columns:repeat(2,minmax(0,1fr));padding:12px;gap:10px}.raffle-controls button{width:100%}}


#danceTimer {
  display: none;
}

/* Паутина только на левой створке */
.door-panel.left {
  position: relative;
}

.door-panel.left::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("images/spider.png");
  background-size: contain;
  background-position: top right;
  background-repeat: no-repeat;
  opacity: 0.75;
  pointer-events: none;
  z-index: 5;
  transform: scaleX(-1);
}

/* Кукла выглядывает из-за левого или правого края */
.scary-doll {
  position: fixed;
  z-index: 5000;
  width: clamp(150px, 24vw, 260px);
  height: auto;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.15s ease;
}

.scary-doll-image {
  display: block;
  width: 100%;
  height: auto;
  object-fit: contain;
  filter: drop-shadow(0 0 15px rgba(180, 0, 0, 0.7));
}

.scary-doll.doll-peek {
  visibility: visible;
  animation: dollPeek 1.2s ease-in-out both;
}

@keyframes dollPeek {
  0% {
    opacity: 0;
    transform: translateX(var(--peek-start)) scale(.9) rotate(var(--peek-tilt));
  }

  25% {
    opacity: 1;
    transform: translateX(0) scale(1.1) rotate(0deg);
  }

  45% {
    opacity: 1;
    transform: translateX(0) scale(1.2) rotate(var(--peek-tilt));
  }

  70% {
    opacity: 1;
    transform: translateX(0) scale(1.3) rotate(var(--peek-tilt));
  }

  100% {
    opacity: 0;
    transform: translateX(var(--peek-start)) scale(.8) rotate(var(--peek-tilt));
  }
}


/* Полноэкранная финальная дверь */
.final-door-overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  display: grid;
  grid-template-columns: 1fr 1fr;
  perspective: 1400px;
  overflow: hidden;
  background: #020308;
  isolation: isolate;
}

.final-door-light {
  position: absolute;
  inset: 0;
  z-index: 0;
  opacity: 0;
  background: radial-gradient(
    ellipse at center,
    #fff5c9 0%,
    #ffbd59 18%,
    #e77a2b 34%,
    #090a12 72%
  );
  transition: opacity 1.4s ease;
}

.final-door-leaf {
  position: relative;
  z-index: 1;
  min-width: 0;
  height: 100%;
  border: 10px ridge #8b603b;
  background: linear-gradient(
    90deg,
    #281307 0%,
    #684025 12%,
    #3b2112 22%,
    #74482a 48%,
    #2d180c 100%
  );
  box-shadow:
    inset 0 0 0 7px #241307,
    inset 0 0 0 15px #8e623b,
    inset 0 0 35px #000;
  transform: rotateY(0deg);
  transition: transform 2.35s cubic-bezier(.18,.7,.12,1);
  backface-visibility: hidden;
}

.final-door-leaf.left {
  transform-origin: left center;
}

.final-door-leaf.right {
  transform-origin: right center;
}

.final-door-handle {
  position: absolute;
  top: 50%;
  width: 20px;
  height: 20px;
  border: 3px solid #38200e;
  border-radius: 50%;
  background: radial-gradient(
    circle at 30% 25%,
    #fff0ad,
    #b27a35 48%,
    #39200e 78%
  );
  box-shadow: 0 0 14px #ffc66a66;
}

.final-door-leaf.left .final-door-handle {
  right: 8%;
}

.final-door-leaf.right .final-door-handle {
  left: 8%;
}

/* Створки открываются в разные стороны */
.final-door-overlay.opening .final-door-leaf.left {
  transform: rotateY(-105deg);
}

.final-door-overlay.opening .final-door-leaf.right {
  transform: rotateY(105deg);
}

.final-door-overlay.opening .final-door-light {
  opacity: 1;
}

/* Учитываем настройки доступности */
@media (prefers-reduced-motion: reduce) {
  .final-door-leaf,
  .final-door-light {
    transition-duration: .01ms;
  }
}